        onDrop={(event) => drop(event, "workspace")}
        onChangesDrop={(event) => drop(event, "working")}
      />
      {#each controller.diffs.filter((diff) => diff.origin === "working" && registeredDiffs.includes(diff.origin)) as diff (diff.origin)}
        <StoreStackWorkspaceDiff {controller} {diff} {onCommand} />
      {/each}
    {/if}
    {#if controller.page === "branches"}
      <ColumnCanvas.Column
        resizable
        fixed
        id="branches"
        aria-label="Branches"
        title="Branches"
        count={stackBookmarks(snapshot).length}
      >
        <ColumnCanvas.Body scrollStrategy="styled">
          <CommunityRepositoryBranchCommand
            hasMore={Boolean(snapshot.branchesNextCursor)}
            loading={controller.branches.loading}
            onLoadMore={() => void controller.branches.load()}
            groupWorkspaceBookmarks
            scrollStrategy="styled"
            targetBookmark={snapshot.target
              ? {
                  name: snapshot.target.name,
                  targets: [snapshot.target.commit],
                  description: snapshot.target.message,
                  author: snapshot.target.author,
                  authorEmail: snapshot.target.email,
                  updatedAt: snapshot.target.createdAt,
                }
              : undefined}
            bookmarks={stackBookmarks(snapshot)}
            selected={controller.targetHistory.active
              ? (snapshot.target?.name ?? "")
              : (controller.selectedBranch ?? "")}
            onSelect={(name) => {
              if (name === snapshot.target?.name) {
                toggleTargetBranch(controller);
                return;
              }
              const stack =
                snapshot.stacks.find((item) => item.name === name) ??
                snapshot.stacks.find((item) =>
                  item.heads.some((head) => head.name === name),
                );
              if (stack) toggleStackBranch(controller, stack.id, name);
              else
                controller.validation =
                  snapshot.branchUnavailableReasons?.[name] ??
                  "This branch is unavailable.";
            }}
          />
        </ColumnCanvas.Body>
      </ColumnCanvas.Column>
      {#if controller.targetHistory.active}
        <StoreStackTargetHistory {controller} />
        {#each controller.targetHistory.diff && registeredDiffs.includes(TARGET_HISTORY_ORIGIN) ? [controller.targetHistory.diff] : [] as diff (diff.origin)}
          <StoreStackWorkspaceDiff {controller} {diff} {onCommand} />
        {/each}
      {/if}
    {/if}
    {#each stacks.filter( (stack) => registeredStacks.includes(stack.id) ) as stack (stack.id)}<StoreStackLane
        {controller}
        {stack}
        {showStackActions}
        applied={[stack.name, ...(stack.heads[0]?.aliases ?? [])].some((name) =>
          isAppliedBranch(snapshot, name),
        )}
        {onCommand}
        onDrop={drop}
      />
      {#each details.filter((detail) => detail.stack === stack.id && registeredDiffs.includes(detail.origin)) as detail (detail.origin)}
        <StoreStackWorkspaceDetailsColumn
          {controller}
          origin={detail.origin}
          branch={detail.branch}
          diff={detail.diff}
          {onCommand}
        />
      {/each}
    {/each}
    {#if controller.forge?.open}<ColumnCanvas.Column
        id="forge-pr"
        resizable
        aria-label="Pull request details"
        ><StoreForgePanel controller={controller.forge} /></ColumnCanvas.Column
      >{/if}
  </ColumnCanvas.Root>
</ScrollArea>

{#if branch}
  <ColumnCanvas.Column
    resizable
    id={TARGET_HISTORY_ORIGIN}
    columnTitle={branch.name}
    aria-label={`Stack ${branch.name}`}
  >
    <ColumnCanvas.Header>
      <GitBranch size={16} aria-hidden="true" />
      <ColumnCanvas.Title>{branch.name}</ColumnCanvas.Title>
      <ColumnCanvas.Count
        >{history.total ?? history.commits.length}</ColumnCanvas.Count
      >
      <ColumnCanvas.HeaderActions>
        <ColumnCanvas.Toggle aria-label={`Collapse ${branch.name}`} />
      </ColumnCanvas.HeaderActions>
    </ColumnCanvas.Header>
    <ColumnCanvas.Body scrollStrategy="styled" orientation="both">
      <StoreNotice
        noticeKey="stack-workspace-target-history"
        title="Branch history unavailable"
        message={history.error}
        lifetime="condition"
      />
      {#if history.error}
        <Button
          size="sm"
          variant="outline"
          disabled={history.loading}
          onclick={() => void history.loadMore()}>Retry branch history</Button
        >
      {/if}
      {#if history.loading && !history.commits.length}
        <CommunityProjectsRepositorySkeleton
          layout="graph"
          label="Loading branch history"
          count={5}
        />
      {:else if !history.commits.length && !history.error}
        <CommunityProjectsColumnAlert
          title="No commits"
          description="The target branch has no history."
        />
      {:else}
        <Card.Root
          class="stack-workspace__bookmark-card"
          style={`min-width: calc(${graphWidth}px + 18rem)`}
          data-loaded-commits={history.commits.length}
        >
          <Card.Header class="stack-workspace__bookmark-header">
            <GitBranch aria-hidden="true" />
            <div>
              <Card.Title
                ><ColumnCanvas.Title>{branch.name}</ColumnCanvas.Title
                ></Card.Title
              >
              <Card.Description>
                <CommunityProjectsGitAuthorAvatar
                  name={branch.author}
                  email={branch.email}
                  size="xsmall"
                />
                {branch.author} · <CommunityRelativeTime
                  timestamp={branch.createdAt}
                />
              </Card.Description>
              <div class="stack-workspace__branch-chips">
                <CommunityChip variant="muted">Workspace target</CommunityChip>
              </div>
            </div>
          </Card.Header>
          <CommunityProjectsRevisionGraph
            {revisions}
            avatarSize="xsmall"
            continuous
            endBorder={false}
            selectedId={history.selectedId}
            graphLabel={`Commits in ${branch.name}`}
            onSelect={(revision) =>
              toggleTargetCommit(controller, revision.eventId)}
            hasMore={history.hasMore && !history.error}
            loading={history.loading}
            onLoadMore={() => void history.loadMore()}
          >
            {#snippet rowActions()}<CommunityChip variant="muted"
                >Immutable</CommunityChip
              >{/snippet}
            {#snippet selectedFiles()}
              {#if selected}
                <StoreStackSourceFiles
                  {controller}
                  source={selected.id}
                  readOnly
                  ariaLabel={`Changed files in ${branch.name}`}
                  selectedPath={history.diff?.source === selected.id
                    ? history.diff.path
                    : null}
                  onSelectPath={(path) => history.selectFile(selected.id, path)}
                />
              {/if}
            {/snippet}
          </CommunityProjectsRevisionGraph>
        </Card.Root>
      {/if}
    </ColumnCanvas.Body>
  </ColumnCanvas.Column>
{/if}

