  --stack-workspace-branch-gap: 0.75rem;
  display: flex;
  width: 100%;
  min-width: 0;
  flex: 1;
  overflow: hidden;
  height: 100%;
  min-height: 0;
  flex-direction: column;
  color: var(--foreground);
  background: var(--background);
}
