  color: var(--muted-foreground);
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
  padding: 0.5rem 1rem;
  border-top: 1px solid var(--border);
  font-size: var(--community-text-secondary);
}
.stack-workspace__stage-card,
.stack-workspace__bookmark-card {
  margin: 0.5rem;
  gap: 0;
  padding-block: 0;
  overflow: hidden;
}
.stack-workspace__stage-content {
  display: grid;
  gap: 0.75rem;
  padding: 0.75rem;
}
.stack-workspace__stage-drop,
.stack-workspace__staged-header {
  background: var(--muted);
}
.stack-workspace__stage-drop {
  padding: 0.375rem;
}
.stack-workspace__stage-start,
.stack-workspace__stage-form {
  border-top: 1px solid var(--border);
}
.stack-workspace__stage-form {
  padding: 0;
  gap: 0;
}
.stack-workspace__staged-header {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.5rem 0.75rem;
  border-bottom: 1px solid var(--border);
}
.stack-workspace__staged-header > svg {
  width: 1rem;
  height: 1rem;
}
.stack-workspace__staged-actions {
  margin-inline-start: auto;
}
.stack-workspace__staged-list {
  padding: 0.25rem 0.5rem;
}
.stack-workspace__drop {
  min-height: 4rem;
  white-space: normal;
  border: 2px dashed var(--border);
  background: transparent;
  color: var(--muted-foreground);
  box-shadow: none;
}
.stack-workspace__commit-fields {
  gap: 0;
}
.stack-workspace__commit-description-row {
  padding: 0.75rem;
}
.stack-workspace__commit-title-row {
  border-bottom: 1px solid var(--border);
  padding: 0.75rem;
}
.stack-workspace__bookmark-header {
  display: grid;
  grid-template-columns: 2rem minmax(0, 1fr);
  align-items: center;
  gap: 0;
  padding: 0.75rem 0;
  border-bottom: 1px solid var(--border);
}
.stack-workspace__bookmark-header > svg {
  margin-inline: 0.75rem;
  width: 1rem;
  height: 1rem;
}
.stack-workspace .stack-workspace__stack-header:hover,
.stack-workspace .stack-workspace__stack-header:focus-within,
.stack-workspace__bookmark-header:hover {
  background: color-mix(in srgb, var(--foreground) 7%, var(--background));
}
.stack-workspace__bookmark-header > div {
  display: grid;
  gap: 0.35rem;
  min-width: 0;
  padding-right: 0.75rem;
}
.stack-workspace__bookmark-header [data-slot="card-description"] {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 0.35rem;
}
.stack-workspace__empty {
  font-size: var(--community-text-secondary);
  padding: 0.75rem;
  margin: 0;
  color: var(--muted-foreground);
}
.stack-workspace__hunks {
  display: grid;
  gap: 0.5rem;
  margin: 0;
  padding: 0.5rem;
}
.stack-workspace__hunk-card {
  padding: 0;
  gap: 0;
  overflow: hidden;
}
.stack-workspace__hunk-card[draggable="true"] {
  cursor: grab;
}
.stack-workspace__hunk-card[draggable="true"]:active {
  cursor: grabbing;
}
.stack-workspace__hunk-header {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.25rem 0.5rem;
  background: var(--muted);
  color: var(--muted-foreground);
  border-bottom: 1px solid var(--border);
}
.stack-workspace__hunk-header code {
  font-family: var(--font-mono);
  font-size: 0.6875rem;
  font-weight: 400;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}
.stack-workspace__hunk-header > label,
.stack-workspace__hunk-header [data-slot="card-title"] {
  flex: 1;
}
.stack-workspace__hunk-content {
  padding: 0;
}
.stack-workspace__bookmarks {
  margin: 0.5rem;
}
.stack-workspace[data-page="workspace"]
  .stack-workspace__stage-card
  + .stack-workspace__bookmarks {
  margin-block-start: var(--stack-workspace-branch-gap);
}
.stack-workspace__bookmarks .stack-workspace__bookmark-card {
  margin: 0;
}
.stack-workspace__bookmark-link {
  display: block;
  width: 100%;
  height: var(--stack-workspace-branch-gap);
}
.stack-workspace__bookmark-actions {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.5rem 0.75rem;
  padding-inline-end: 0.5rem;
  border-bottom: 1px solid var(--border);
  background: color-mix(in srgb, var(--foreground) 4%, var(--background));
}
.stack-workspace__bookmark-menu {
  margin-inline-start: auto;
}
.stack-workspace__menu-trigger {
  --accent: color-mix(in srgb, var(--foreground) 24%, var(--background));
  --muted: var(--accent);
  --ui-column-canvas-header-action-hover: var(--accent);
}
.stack-workspace__request {
  overflow-wrap: anywhere;
  font-size: var(--community-text-secondary);
}
.stack-workspace__folder {
  overflow-wrap: anywhere;
}
@media (max-width: 600px) {
  .stack-workspace__footer {
    padding: 0.5rem;
  }
}

.stack-workspace__branch-title {
  border: 0;
  background: transparent;
  color: inherit;
  padding: 0;
  font: inherit;
  text-align: left;
  cursor: pointer;
}
.stack-workspace__branch-title:focus-visible {
  outline: 2px solid var(--ring);
  outline-offset: 3px;
  border-radius: 0.25rem;
}

.stack-workspace__commit-actions {
  display: flex;
  gap: 0.5rem;
  padding: 0.75rem;
}
.stack-workspace__commit-actions > button {
  flex: 1;
}

.stack-workspace__views {
  gap: 0;
}
.stack-workspace__action-menu {
  width: max-content;
  min-width: min(18rem, var(--bits-dropdown-menu-content-available-width));
  max-width: var(--bits-dropdown-menu-content-available-width);
}
.stack-workspace__stack-header,
.stack-workspace__bookmark-header {
  cursor: pointer;
}

/* Changeyard's rounded selected marker, adapted without changing row geometry. */
.stack-workspace__branch-files {
  padding: 0.5rem;
  padding-inline-start: 2rem;
}
.stack-workspace__bookmark-header[data-selected] {
  border-bottom: 0;
}
.stack-workspace__branch-chips {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.35rem;
}
.stack-workspace__bookmark-card .community-chip[data-chip-tone="neutral"] {
  background: color-mix(in srgb, var(--foreground) 14%, var(--background));
  border-color: color-mix(in srgb, var(--foreground) 22%, var(--background));
}
.stack-workspace__bookmark-header[data-selected]::before,
.stack-workspace
  .community-revision-graph__item--selected
  > .community-revision-graph__row::before {
  content: "";
  position: absolute;
  left: 0;
  top: 50%;
  width: 4px;
  height: 3rem;
  max-height: calc(100% - 0.5rem);
  transform: translateY(-50%);
  border-radius: 0 999px 999px 0;
  background: var(--primary);
  pointer-events: none;
}

.stack-workspace .community-chip.stack-workspace__conflict-count {
  min-width: 1.125rem;
  height: 1.125rem;
  min-height: 1.125rem;
  padding-inline: 0.125rem;
  border-radius: 999px;
  flex-shrink: 0;
}

.stack-workspace__branch-title-row {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  min-width: 0;
}
.stack-workspace__branch-title-row > [data-slot="card-title"] {
  flex: 1;
  min-width: 0;
}
.stack-workspace__branch-title-row .stack-workspace__branch-title {
  display: block;
  width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

