{#snippet options()}
  <Menu.Group
    >{#each items as item (item.label)}
      <Menu.Item aria-label={item.label} onSelect={() => void copy(item)}
        ><Copy aria-hidden="true" />{item.label}</Menu.Item
      >
    {/each}</Menu.Group
  >
{/snippet}
{#if submenu}<Menu.Sub
    ><Menu.SubTrigger><Copy aria-hidden="true" />Copy</Menu.SubTrigger>
    <Menu.SubContent class="stack-workspace__action-menu"
      >{@render options()}</Menu.SubContent
    >
  </Menu.Sub>{:else}{@render options()}{/if}

layoutAdaptations.after:
{#snippet options()}
  <Menu.Group
    >{#each items as item (item.label)}
      <Menu.Item aria-label={item.label} onSelect={() => void copy(item)}
        ><Copy aria-hidden="true" />{item.label}</Menu.Item
      >
    {/each}</Menu.Group
  >
{/snippet}
{#if submenu}<Menu.Sub
    ><Menu.SubTrigger><Copy aria-hidden="true" />Copy</Menu.SubTrigger>
    <Menu.SubContent class="workspace-action-menu"
      >{@render options()}</Menu.SubContent
    >
  </Menu.Sub>{:else}{@render options()}{/if}

layoutAdaptations.before:
{#snippet header()}
  <ColumnCanvas.Header
    ><ColumnCanvas.Title>{file?.path ?? "Diff"}</ColumnCanvas.Title
    ><ColumnCanvas.HeaderActions>
      {#if file}
        <CommunityDiffControls bind:viewMode bind:wrap />
        {#if selection && diff.source === "unassigned" && controller.snapshot?.capabilities.includes("discard")}
          <Tooltip.Provider
            ><Tooltip.Root
              ><Tooltip.Trigger
                >{#snippet child({ props })}<Button
                    {...props}
                    variant="ghost"
                    size="icon-sm"
                    aria-label="Discard selected changes"
                    disabled={!controller.can("discard") || !hasSelection}
                    onclick={() =>
                      selection &&
                      onCommand({ kind: "discard", selections: [selection] })}
                    ><Trash aria-hidden="true" /></Button
                  >{/snippet}</Tooltip.Trigger
              ><Tooltip.Content>Discard selected changes</Tooltip.Content
              ></Tooltip.Root
            ></Tooltip.Provider
          >
        {/if}
        {#if selection && diff.source !== "unassigned"}
          <Tooltip.Provider
            ><Tooltip.Root
              ><Tooltip.Trigger>
                {#snippet child({ props })}
                  <Button
                    {...props}
                    variant="ghost"
                    size="icon-sm"
                    aria-label="Split selected changes"
                    disabled={!controller.can("split") || !hasSelection}
                    onclick={() =>
                      selection &&
                      onCommand({
                        kind: "split",
                        commit: selection.source,
                        message: "",
                        selection,
                      })}><Columns aria-hidden="true" /></Button
                  >
                {/snippet}
              </Tooltip.Trigger><Tooltip.Content
                >Split selected changes</Tooltip.Content
              ></Tooltip.Root
            ></Tooltip.Provider
          >
        {/if}
      {/if}
      {#if embedded}<Button
          variant="ghost"
          size="icon-sm"
          aria-label="Close file diff"
          onclick={() => controller.closeDiff(diff.origin)}
          ><X aria-hidden="true" /></Button
        >
      {:else}<ColumnCanvas.Close
          aria-label="Close Diff column"
          onclick={() => controller.closeDiff(diff.origin)}
        />{/if}</ColumnCanvas.HeaderActions
    ></ColumnCanvas.Header
  >
{/snippet}
{#snippet unavailable()}
  {#if file?.content?.status === "unavailable"}
    <CommunityProjectsColumnAlert
      description={`This file cannot be displayed as a text diff (${file.content.reason.replaceAll("_", " ")}).`}
    />
  {/if}
{/snippet}
{#snippet content()}
  <StoreNotice
    noticeKey={`stack-files:${diff.source}`}
    title="Changed files unavailable"
    message={filesState.error}
    lifetime="condition"
  />
  <StoreNotice
    noticeKey={`stack-patch:${diff.source}:${diff.path}`}
    title="Diff unavailable"
    message={patchRead.error}
    lifetime="condition"
  />
  {#if patchRead.error}<Button
      size="sm"
      variant="outline"
      onclick={() => void controller.details.loadDiff(diff.source, diff.path)}
      >Retry diff</Button
    >{/if}
  {#if controller.details.lazy && !file}
    {#if filesState.error}<Button
        size="sm"
        variant="outline"
        onclick={() => void controller.details.loadFiles(diff.source)}
        >Retry changed files</Button
      >
    {:else}<CommunityProjectsRepositorySkeleton
        layout="diff"
        label={`Loading diff for ${diff.path}`}
        count={3}
      />{/if}
  {:else if file?.content?.status === "unloaded" && !patchRead.error}
    <CommunityProjectsRepositorySkeleton
      layout="diff"
      label={`Loading diff for ${diff.path}`}
      count={3}
    />
  {:else if file && file.content?.status !== "unavailable" && !file.hunks.length && !patchRead.error}
    <CommunityProjectsColumnAlert
      title="No text changes"
      description="There are no changed text hunks for this file."
    />
  {:else if file && file.content?.status !== "unavailable"}
    {#if controller.details.lazy && workspaceAggregateSource(diff.source) && !file.selectionSource}
      <p class="stack-workspace__empty">
        This comparison has no single movable commit delta. Select an individual
        commit to move its changes.
      </p>
    {/if}
    <section
      class="stack-workspace__hunks"
      aria-label={`Diff hunks from ${diff.origin} · ${file.path}`}
    >
      {#each file.hunks as hunk (hunk.id)}
        <StoreStackDiffHunk
          {hunk}
          displayPatch={context.get(hunk.id)}
          drag={controller.drag}
          origin={diff.origin}
          path={file.path}
          selection={diff.origin === TARGET_HISTORY_ORIGIN ||
          !executable ||
          (controller.details.lazy &&
            !/^native:[0-9a-f]{64}$/u.test(hunk.id)) ||
          !controller.can("transfer")
            ? null
            : workspaceHunkSelection(
                controller.snapshot!,
                selectionSource,
                file.path,
                hunk.id,
              )}
          checked={!selection?.hunks || selection.hunks.includes(hunk.id)}
          selectable={Boolean(selection) &&
            (!controller.details.lazy ||
              /^native:[0-9a-f]{64}$/u.test(hunk.id))}
          disabled={controller.locked}
          {viewMode}
          {wrap}
          onChecked={(checked) => choose(hunk.id, checked)}
          onAssign={(selection) =>
            onCommand({ kind: "transfer", selection, target: "" })}
        />
      {/each}
    </section>
  {/if}
{/snippet}

{#if embedded}
  <section
    class="stack-workspace-details__file"
    aria-label="Selected file diff"
  >
    {@render header()}
    {@render unavailable()}
    <div class="stack-workspace-details__patch">{@render content()}</div>
  </section>
{:else}
  <ColumnCanvas.Column
    resizable
    id={`diff-${diff.origin}`}
    aria-label={`Selected changes from ${diff.origin}`}
  >
    {@render header()}
    {@render unavailable()}
    <ColumnCanvas.Body scrollStrategy="styled"
      >{@render content()}</ColumnCanvas.Body
    >
  </ColumnCanvas.Column>
{/if}

{#if pr}
  {#key pr.number}
    <StoreDetachablePanel title={`PR #${pr.number} · ${pr.head}`}>
      {#snippet children({ floating, toggle })}
        <section
          class="forge-inline"
          class:forge-inline--floating={floating}
          data-forge-summary
          aria-label={`Pull request for ${branch}`}
        >
          <Collapsible.Root
            open={expanded}
            onOpenChange={expand}
            disabled={floating}
          >
            <header class="forge-inline__summary">
              <StoreForgeIcon
                provider={controller.data?.connection?.provider}
              />
              <h2
                class="forge-inline__title"
                aria-label={selected ? controller.title || pr.title : pr.title}
              >
                <Collapsible.Trigger>
                  {#snippet child({ props })}
                    <Button
                      {...props}
                      variant="ghost"
                      size="sm"
                      aria-label={`${expanded ? "Collapse" : "Expand"} pull request #${pr.number}`}
                    >
                      {#if expanded}<ChevronDown
                          aria-hidden="true"
                        />{:else}<ChevronRight aria-hidden="true" />{/if}
                      <span
                        >{selected
                          ? controller.title || pr.title
                          : pr.title}</span
                      >
                    </Button>
                  {/snippet}
                </Collapsible.Trigger>
              </h2>
              <a
                class="forge-pr__number"
                href={pr.url}
                target="_blank"
                rel="noreferrer">#{pr.number}</a
              >
              <CommunityChip variant="muted"
                >{pr.draft ? "Draft" : pr.state}</CommunityChip
              >
              <div class="forge-inline__actions forge-header-actions">
                <Tooltip.Provider>
                  <Tooltip.Root
                    ><Tooltip.Trigger
                      >{#snippet child({ props })}
                        <Button
                          {...props}
                          variant="ghost"
                          size="icon-sm"
                          aria-label="Edit details"
                          aria-pressed={editing}
                          disabled={blocked ||
                            !controller.data?.capabilities.edit}
                          onclick={async () => {
                            if (!expanded) {
                              expand(true);
                              await tick();
                            }
                            editing = !editing;
                          }}><Pencil aria-hidden="true" /></Button
                        >
                      {/snippet}</Tooltip.Trigger
                    ><Tooltip.Content>Edit details</Tooltip.Content
                    ></Tooltip.Root
                  >
                  <Tooltip.Root
                    ><Tooltip.Trigger
                      >{#snippet child({ props })}
                        <Button
                          {...props}
                          variant="ghost"
                          size="icon-sm"
                          aria-label={floating
                            ? "Dock PR details"
                            : "Float PR details"}
                          onclick={() => {
                            if (!expanded) expand(true);
                            toggle();
                          }}><PictureInPicture2 aria-hidden="true" /></Button
                        >
                      {/snippet}</Tooltip.Trigger
                    ><Tooltip.Content
                      >{floating
                        ? "Dock PR details"
                        : "Float PR details"}</Tooltip.Content
                    ></Tooltip.Root
                  >
                </Tooltip.Provider>
                <StoreForgePullRequestActions {controller} {branch} />
                <Button
                  variant="ghost"
                  size="icon-sm"
                  aria-label="Close details column"
                  onclick={onClose}><X aria-hidden="true" /></Button
                >
              </div>
            </header>
            <Collapsible.Content>
              {#if expanded}
                <div class="forge-inline__details">
                  <StoreForgePullRequest {controller} bind:editing />
                </div>
              {/if}
            </Collapsible.Content>
          </Collapsible.Root>
        </section>
      {/snippet}
    </StoreDetachablePanel>
  {/key}
{/if}

layoutAdaptations.after:
{#if pr}
  {#key review.key(pr)}
    <Detachable title={`PR #${pr.number} · ${pr.head}`}>
      {#snippet children({ floating, toggle })}
        <section
          class="repository-pr"
          class:repository-pr--floating={floating}
          aria-label={`Pull request for ${branch}`}
        >
          <Collapsible.Root
            open={expanded}
            onOpenChange={expand}
            disabled={floating}
          >
            <header class="repository-pr__summary">
              <GitPullRequest
                aria-label={pr.provider === "github" ? "GitHub" : "Forgejo"}
                size={16}
              />
              <h2 class="repository-pr__title">
                <Collapsible.Trigger>
                  {#snippet child({ props })}<Button
                      {...props}
                      variant="ghost"
                      size="sm"
                      aria-label={`${review.drafts[review.key(pr)]?.title || pr.title} · ${expanded ? "Collapse" : "Expand"} pull request #${pr.number}`}
                    >
                      {#if expanded}<ChevronDown
                          aria-hidden="true"
                        />{:else}<ChevronRight aria-hidden="true" />{/if}
                      <span
                        >{review.drafts[review.key(pr)]?.title ||
                          pr.title}</span
                      >
                    </Button>{/snippet}
                </Collapsible.Trigger>
              </h2>
              <a
                class="repository-pr__number"
                href={pr.url}
                target="_blank"
                rel="noreferrer">#{pr.number}</a
              >
              <Badge variant="secondary">{pr.draft ? "Draft" : pr.state}</Badge>
              <div class="repository-pr__actions">
                <Tooltip.Provider>
                  <Tooltip.Root
                    ><Tooltip.Trigger
                      >{#snippet child({ props })}<Button
                          {...props}
                          variant="ghost"
                          size="icon-sm"
                          aria-label="Edit PR details"
                          aria-pressed={review.drafts[review.key(pr)]
                            ?.editing ?? false}
                          disabled={blocked ||
                            !onAction ||
                            !pr.capabilities.includes("edit")}
                          onclick={() => {
                            expand(true);
                            const draft = review.draft(pr);
                            draft.editing = !draft.editing;
                          }}><Pencil aria-hidden="true" /></Button
                        >{/snippet}</Tooltip.Trigger
                    ><Tooltip.Content>Edit details</Tooltip.Content
                    ></Tooltip.Root
                  >
                  <Tooltip.Root
                    ><Tooltip.Trigger
                      >{#snippet child({ props })}<Button
                          {...props}
                          variant="ghost"
                          size="icon-sm"
                          aria-label={floating
                            ? "Dock PR details"
                            : "Float PR details"}
                          onclick={() => {
                            expand(true);
                            toggle();
                          }}><PictureInPicture2 aria-hidden="true" /></Button
                        >{/snippet}</Tooltip.Trigger
                    ><Tooltip.Content
                      >{floating
                        ? "Dock PR details"
                        : "Float PR details"}</Tooltip.Content
                    ></Tooltip.Root
                  >
                </Tooltip.Provider>
                <Actions {review} {pr} disabled={blocked} {onAction} />
                <Button
                  variant="ghost"
                  size="icon-sm"
                  aria-label="Close PR details"
                  onclick={onClose}><X aria-hidden="true" /></Button
                >
              </div>
            </header>
            <Collapsible.Content>
              {#if expanded}<Body
                  {review}
                  {pr}
                  disabled={blocked}
                  {onAction}
                />{/if}
            </Collapsible.Content>
          </Collapsible.Root>
        </section>
      {/snippet}
    </Detachable>
  {/key}
{/if}

layoutAdaptations.before:
{#if controller.selected && controller.data}
  {@const pr = controller.selected}
  <section class="forge-pr" aria-label={`PR ${pr.number}`}>
    <div class="forge-pr__content">
      {#if editing}
        <label
          >Title<Input
            bind:value={controller.title}
            oninput={() => (controller.draftDirty = true)}
            disabled={blocked || !controller.data.capabilities.edit}
          /></label
        >
      {/if}
      <p class="forge-pr__branches">
        <code>{pr.head}</code><span aria-label="into">→</span><code
          >{pr.base}</code
        >
      </p>
      <StoreForgeDescription
        bind:value={
          () => controller.body,
          (value) => {
            controller.body = value;
            controller.draftDirty = true;
          }
        }
        bind:editing
        showEditButton={false}
        disabled={blocked || !controller.data.capabilities.edit}
      />
      {#if controller.draftDirty || editing}
        <Button
          disabled={blocked ||
            !controller.draftDirty ||
            !controller.data.capabilities.edit}
          onclick={async () => {
            await controller.edit();
            if (!controller.draftDirty) editing = false;
          }}>Save changes</Button
        >
      {/if}
      {#if controller.merge}<p role="status">
          Merge: {controller.merge.state}
        </p>{/if}
    </div>
    <StoreForgeChecks {controller} />
    <StoreForgePullRequestActions {controller} footer />
  </section>
{/if}

{#if pr && controller.data}
  <section class="forge-checks" aria-label="CI checks">
    <div class="forge-checks__summary">
      <Button
        variant="ghost"
        class="forge-checks__disclosure"
        aria-label="Toggle check results"
        aria-expanded={view.expanded}
        aria-controls={`${id}-results`}
        onclick={() => (view.expanded = !view.expanded)}
      >
        <StoreForgeChecksRing checks={checks?.checks ?? []} state={status} />
        <span class="forge-checks__name"
          ><span role="heading" aria-level={3}
            >{controller.activeRun
              ? `Jobs for run ${controller.activeRun}`
              : summary}</span
          ><span>{counts}</span></span
        >
      </Button>
      <Button
        variant="ghost"
        size="icon-xs"
        aria-label="Refresh checks"
        disabled={blocked || !controller.data.capabilities.checks}
        onclick={() => controller.refreshChecks()}
        ><RefreshCw aria-hidden="true" /></Button
      >
      <Menu.Root
        ><Menu.Trigger
          >{#snippet child({ props })}<Button
              {...props}
              variant="ghost"
              size="icon-xs"
              aria-label="Check display options"
              ><Settings2 aria-hidden="true" /></Button
            >{/snippet}</Menu.Trigger
        >
        <Menu.Content align="end" preventScroll={false} style={forgeMenuLayout}
          ><Menu.RadioGroup
            value={view.grouped ? "status" : "none"}
            onValueChange={(value) => (view.grouped = value === "status")}
          >
            <Menu.RadioItem value="status"
              ><ListFilter aria-hidden="true" />Group by status</Menu.RadioItem
            ><Menu.RadioItem value="none"
              ><List aria-hidden="true" />No grouping</Menu.RadioItem
            >
          </Menu.RadioGroup></Menu.Content
        >
      </Menu.Root>
      <Button
        variant="ghost"
        size="icon-xs"
        class="forge-checks__chevron"
        aria-label={view.expanded ? "Collapse checks" : "Expand checks"}
        aria-expanded={view.expanded}
        aria-controls={`${id}-results`}
        onclick={() => (view.expanded = !view.expanded)}
        >{#if view.expanded}<ChevronDown
            aria-hidden="true"
          />{:else}<ChevronRight aria-hidden="true" />{/if}</Button
      >
    </div>
    <div id={`${id}-results`} hidden={!view.expanded}>
      {#if checks}
        <p class="forge-checks__revision">
          {current ? "Revision" : "Observed revision"}
          <code>{checks.sha.slice(0, 8)}</code>{checks.complete
            ? ""
            : " · Results incomplete"}
        </p>
        {#if controller.activeRun}<Button
            variant="ghost"
            size="xs"
            disabled={blocked}
            onclick={() => controller.act({ kind: "checks" })}
            >Back to all checks</Button
          >{/if}
        <ScrollArea
          scrollStrategy="styled"
          bind:viewportRef={viewport}
          class="forge-checks__scroll"
          aria-label="Check results"
        >
          {#if view.grouped}
            {#each groups as group (group.id)}
              <div class="forge-checks__group">
                <Button
                  variant="ghost"
                  size="sm"
                  class="forge-checks__group-heading"
                  aria-expanded={!view.collapsed[group.id]}
                  aria-controls={`${id}-${group.id}`}
                  onclick={() =>
                    (view.collapsed[group.id] = !view.collapsed[group.id])}
                >
                  {group.checks.length}
                  {group.label}
                  {group.checks.length === 1 ? "check" : "checks"}
                  {#if view.collapsed[group.id]}<ChevronRight
                      aria-hidden="true"
                    />{:else}<ChevronDown aria-hidden="true" />{/if}
                </Button>
                <ul
                  id={`${id}-${group.id}`}
                  hidden={view.collapsed[group.id]}
                  class="forge-checks__list"
                >
                  {#each group.checks as check (check.id)}<StoreForgeCheckRow
                      {controller}
                      {check}
                    />{/each}
                </ul>
              </div>
            {/each}
          {:else}<ul class="forge-checks__list">
              {#each checks.checks as check (check.id)}<StoreForgeCheckRow
                  {controller}
                  {check}
                />{/each}
            </ul>{/if}
        </ScrollArea>
      {/if}
      {#if controller.logs}<pre
          aria-label="Job logs">{controller.logs}</pre>{/if}
    </div>
  </section>
{/if}

{#snippet methodOptions()}
  <Menu.Group>
    <Menu.Label>Merge method</Menu.Label>
    <Menu.RadioGroup
      value={method}
      onValueChange={(value) => (controller.mergeMethod = value)}
    >
      {#each methods as option}
        <Menu.RadioItem
          value={option}
          disabled={blocked || !controller.data?.capabilities.merge}
        >
          {#if option === "merge"}<GitMerge
              aria-hidden="true"
            />{:else if option === "squash"}<Combine
              aria-hidden="true"
            />{:else}<GitBranch aria-hidden="true" />{/if}
          {footer ? fullMethodLabel(option) : methodLabel(option)}
        </Menu.RadioItem>
      {/each}
    </Menu.RadioGroup>
  </Menu.Group>
{/snippet}
{#if pr}
  {#if footer}
    <footer
      class="forge-merge"
      role="group"
      aria-label="Pull request merge actions"
    >
      <div class="forge-merge__status">
        {#if pr.mergeable === true}<CircleCheck
            aria-hidden="true"
          />{:else if pr.mergeable === false}<CircleX
            aria-hidden="true"
          />{:else}<CircleHelp aria-hidden="true" />{/if}
        <div>
          <strong
            >{pr.state === "merged"
              ? "Pull request merged"
              : pr.state !== "open"
                ? "Pull request closed"
                : pr.draft
                  ? "Draft pull request"
                  : pr.mergeable === true
                    ? "No conflicts with base branch"
                    : pr.mergeable === false
                      ? "Conflicts with base branch"
                      : "Mergeability needs refresh"}</strong
          >
          <span
            >{pr.draft
              ? "Mark ready for review before merging."
              : "Forge protection and stack order are checked before merging."}</span
          >
        </div>
      </div>
      {#if pr.state === "open"}
        <div class="forge-merge__bar">
          <div class="forge-merge__buttons">
            <Button
              variant="outline"
              size="sm"
              disabled={mergeDisabled}
              onclick={() => {
                select();
                mergeConfirm = true;
              }}
              ><GitMerge data-icon="inline-start" />{!method
                ? "Merge unavailable"
                : method === "merge"
                  ? "Merge pull request"
                  : fullMethodLabel(method)}</Button
            >
            <Menu.Root
              ><Menu.Trigger
                >{#snippet child({ props })}<Button
                    {...props}
                    variant="outline"
                    size="icon-sm"
                    disabled={blocked ||
                      !methods.length ||
                      !controller.data?.capabilities.merge}
                    aria-label="Choose merge method"
                    ><ChevronDown aria-hidden="true" /></Button
                  >{/snippet}</Menu.Trigger
              >
              <Menu.Content
                align="start"
                preventScroll={false}
                style={forgeMenuLayout}>{@render methodOptions()}</Menu.Content
              >
            </Menu.Root>
          </div>
          {#if merge?.receipt}<Button
              variant="ghost"
              size="sm"
              disabled={blocked}
              onclick={() =>
                controller.act({
                  kind: "merge_status",
                  receipt: merge.receipt!,
                })}
              ><RefreshCw data-icon="inline-start" />Check merge result</Button
            >{/if}
        </div>
      {/if}
    </footer>
  {:else}
    <Menu.Root>
      <Menu.Trigger>
        {#snippet child({ props })}
          <Button
            {...props}
            variant="ghost"
            size="icon-sm"
            aria-label={`PR actions: ${method ? methodLabel(method) : "Merge unavailable"}`}
            title="PR actions"
            disabled={blocked}
          >
            <Ellipsis aria-hidden="true" />
          </Button>
        {/snippet}
      </Menu.Trigger>
      <Menu.Content align="end" preventScroll={false} style={forgeMenuLayout}>
        <Menu.Group>
          <Menu.Label>Pull request actions</Menu.Label>
          <Menu.Item disabled={blocked} onSelect={() => controller.refresh()}
            ><RefreshCw aria-hidden="true" />Refresh pull request</Menu.Item
          >
          {#if controller.data?.capabilities.draft}
            <Menu.Item
              disabled={blocked || pr.state !== "open"}
              onSelect={() => {
                select();
                void controller.act({ kind: "draft", draft: !pr.draft });
              }}
              >{#if pr.draft}<CircleCheck
                  aria-hidden="true"
                />{:else}<FilePenLine aria-hidden="true" />{/if}{pr.draft
                ? "Ready for review"
                : "Convert to draft"}</Menu.Item
            >
          {/if}
          <Menu.Item
            disabled={blocked}
            onSelect={() => {
              select();
              void controller.previewRestack(pr.head);
            }}><Layers aria-hidden="true" />Restack…</Menu.Item
          >
          <Menu.Item
            disabled={mergeDisabled}
            onSelect={() => {
              select();
              mergeConfirm = true;
            }}
            ><GitMerge aria-hidden="true" />{pr.native_stack
              ? "Merge through this PR…"
              : "Merge next…"}</Menu.Item
          >
          {#if merge}
            <Menu.Label>Merge: {merge.state}</Menu.Label>
            {#if merge.receipt}<Menu.Item
                disabled={blocked}
                onSelect={() => {
                  select();
                  void controller.act({
                    kind: "merge_status",
                    receipt: merge.receipt!,
                  });
                }}><RefreshCw aria-hidden="true" />Check merge result</Menu.Item
              >{/if}
          {/if}
        </Menu.Group>
        {#if pr.state === "open"}
          <Menu.Separator />
          {@render methodOptions()}
        {/if}
      </Menu.Content>
    </Menu.Root>
  {/if}
  <Dialog.Root bind:open={mergeConfirm}>
    <Dialog.Content>
      <Dialog.Header>
        <Dialog.Title>Merge PR #{pr.number}?</Dialog.Title>
        <Dialog.Description
          >{pr.native_stack
            ? "Merge this PR and its lower stack dependencies using forge protection rules?"
            : `Merge PR #${pr.number} into ${pr.base}?`}</Dialog.Description
        >
      </Dialog.Header>
      <Dialog.Footer>
        <Button variant="outline" onclick={() => (mergeConfirm = false)}
          >Cancel</Button
        >
        <Button
          disabled={mergeDisabled}
          onclick={() => {
            mergeConfirm = false;
            void controller.act({
              kind: "merge",
              method,
              expected_sha: pr.sha,
            });
          }}>Confirm merge</Button
        >
      </Dialog.Footer>
    </Dialog.Content>
  </Dialog.Root>
{/if}

